1	package ociresources
2	
3	import (
4		"context"
5		"fmt"
6		"sort"
7		"sync"
8		"testing"
9	
10		tea "charm.land/bubbletea/v2"
11	
12		"github.com/anthnel/devdesk/internal/ui/components"
13		"github.com/anthnel/devdesk/internal/ui/testutil"
14	)
15	
16	// "Open tags" (DEVDESK-300, IS-11): the button that always lists the tags of
17	// the typed name, whatever the name looks like and whether or not a Searcher is
18	// wired. These tests call submit(action) directly after typing the name.
19	
20	// fullTagCall is one request the tag lookup sent to a registry.
21	type fullTagCall struct{ apiURL, repo, user, pass string }
22	
23	type fullTagCalls struct {
24		mu    sync.Mutex
25		calls []fullTagCall
26	}
27	
28	// withFullTagRecorder swaps the listRegistryTags seam for a recorder of every
29	// argument that reaches the registry (withTagRecorder keeps only the repo).
30	func withFullTagRecorder(t *testing.T) *fullTagCalls {
31		t.Helper()
32		r := &fullTagCalls{}
33		prev := listRegistryTags
34		listRegistryTags = func(_ context.Context, apiURL, repo, user, pass string) ([]string, error) {
35			r.mu.Lock()
36			defer r.mu.Unlock()
37			r.calls = append(r.calls, fullTagCall{apiURL, repo, user, pass})
38			return []string{"v1", "latest"}, nil
39		}
40		t.Cleanup(func() { listRegistryTags = prev })
41		return r
42	}
43	
44	// sorted returns the calls as strings, in a stable order.
45	func (r *fullTagCalls) sorted() []string {
46		r.mu.Lock()
47		defer r.mu.Unlock()
48		out := make([]string, 0, len(r.calls))
49		for _, c := range r.calls {
50			out = append(out, fmt.Sprintf("%q", []string{c.apiURL, c.repo, c.user, c.pass}))
51		}
52		sort.Strings(out)
53		return out
54	}
55	
56	func (r *fullTagCalls) repos() []string {
57		r.mu.Lock()
58		defer r.mu.Unlock()
59		out := make([]string, 0, len(r.calls))
60		for _, c := range r.calls {
61			out = append(out, c.repo)
62		}
63		sort.Strings(out)
64		return out
65	}
66	
67	// openedTags is everything observable about a submit that lists tags.
68	type openedTags struct {
69		state    browserState
70		requests []string // what reached the registries
71		msgs     []string // MultiRegistryTagsLoadedMsg minus Gen, sorted
72		refs     []string // multiImageName of every table row, sorted
73		cmdNil   bool
74	}
75	
76	// runTagSubmit types name, calls submit(action) and plays the answers back.
77	func runTagSubmit(t *testing.T, m Model, name string, action formAction, rec *fullTagCalls) openedTags {
78		t.Helper()
79		m = typeInto(t, m, name)
80		_, cmd := m.registryBrowser.submit(action)
81		out := openedTags{state: m.registryBrowser.state, cmdNil: cmd == nil}
82		var loaded []tea.Msg
83		for _, msg := range testutil.Msgs(cmd) {
84			v, ok := msg.(MultiRegistryTagsLoadedMsg)
85			if !ok {
86				continue
87			}
88			loaded = append(loaded, v)
89			v.Gen = 0
90			out.msgs = append(out.msgs, fmt.Sprintf("%#v", v))
91		}
92		m = feed(t, m, loaded...)
93		for _, tag := range m.registryBrowser.tags {
94			out.refs = append(out.refs, multiImageName(tag.RegistryURL, tag.Repo, tag.Tag))
95		}
96		sort.Strings(out.msgs)
97		sort.Strings(out.refs)
98		out.requests = rec.sorted()
99		return out
100	}
101	
102	func sameList(a, b []string) bool { return sameStrings(a, b) }
103	
104	// c.2: the former "Browse Tags" (no Searcher, submitSearch) and the new
105	// "Open tags" (a Searcher wired, actionOpenTags) are the same flow.
106	func TestOpenTagsMatchesTheFormerBrowseTagsToTheCharacter(t *testing.T) {
107		for _, tc := range []struct {
108			name    string
109			model   func(*testing.T) Model
110			typed   string
111			wantLen int
112		}{
113			{"short name, flat registries", browsingModel, "nginx", 2},
114			{"short name, grouped registries", groupedModel, "nginx", 3},
115			{"name with a slash, flat registries", browsingModel, "myorg/api", 2},
116			{"name with a slash, grouped registries", groupedModel, "myorg/api", 3},
117		} {
118			t.Run(tc.name, func(t *testing.T) {
119				// Former behaviour: no Searcher, the single "Browse Tags" button.
120				withImageSearcher(t, nil)
121				recOld := withFullTagRecorder(t)
122				old := runTagSubmit(t, tc.model(t), tc.typed, actionSearch, recOld)
123	
124				// New behaviour: a Searcher is wired, "Open tags" is pressed.
125				fake := &fakeSearcher{}
126				withImageSearcher(t, fake)
127				recNew := withFullTagRecorder(t)
128				got := runTagSubmit(t, tc.model(t), tc.typed, actionOpenTags, recNew)
129	
130				if len(old.requests) != tc.wantLen {
131					t.Fatalf("reference flow sent %d requests, want %d (%v): fixture drifted", len(old.requests), tc.wantLen, old.requests)
132				}
133				if old.state != browserStateTags {
134					t.Fatalf("reference flow state = %d, want browserStateTags", old.state)
135				}
136				if got.state != old.state {
137					t.Errorf("state = %d, want %d", got.state, old.state)
138				}
139				if got.cmdNil {
140					t.Fatal("Open tags returned no Cmd")
141				}
142				if !sameList(got.requests, old.requests) {
143					t.Errorf("requests differ\n got  %v\n want %v", got.requests, old.requests)
144				}
145				if !sameList(got.msgs, old.msgs) {
146					t.Errorf("messages differ\n got  %v\n want %v", got.msgs, old.msgs)
147				}
148				if !sameList(got.refs, old.refs) || len(got.refs) == 0 {
149					t.Errorf("image references differ\n got  %v\n want %v", got.refs, old.refs)
150				}
151				if fake.calls() != 0 {
152					t.Errorf("the Searcher was called %d times by Open tags", fake.calls())
153				}
154			})
155		}
156	}
