172			if r == "docker-hosted/library/nginx" || r == "dhi-proxy/library/nginx" ||
173				r == "docker-hosted/docker-hosted/nginx" || r == "dhi-proxy/dhi-proxy/nginx" {
174				t.Errorf("wrong repository %q", r)
175			}
176		}
177		if fake.calls() != 0 {
178			t.Errorf("the Searcher was called %d times", fake.calls())
179		}
180	}
