182	func TestOpenTagsNeverCallsTheSearcher(t *testing.T) {
183		fake := &fakeSearcher{}
184		withImageSearcher(t, fake)
185		rec := withFullTagRecorder(t)
186	
187		m := typeInto(t, browsingModel(t), "nginx")
188		_, cmd := m.registryBrowser.submit(actionOpenTags)
189		testutil.Msgs(cmd)
190	
191		if m.registryBrowser.state != browserStateTags {
