202	// c.3: the search action is the IS-01 search, not the tags.
203	func TestSearchActionOnAShortNameSearches(t *testing.T) {
204		fake := &fakeSearcher{}
205		withImageSearcher(t, fake)
206		rec := withFullTagRecorder(t)
207	
208		m := typeInto(t, browsingModel(t), "nginx")
