274			want := checkedKeys(m)
275			m = typeInto(t, m, "nginx")
276			_, cmd := m.registryBrowser.submit(actionSearch)
277			testutil.Msgs(cmd)
278			if got := fake.keys(); !sameList(got, want) {
279				t.Errorf("searched %v, want %v", got, want)
280			}
281		})
282	}
