311			t.Run(fmt.Sprintf("action %d no registry", action), func(t *testing.T) {
312				fake := &fakeSearcher{}
313				withImageSearcher(t, fake)
314				rec := withFullTagRecorder(t)
315	
316				m := browsingModel(t)
317				uncheckAll(m)
318				m = typeInto(t, m, "nginx")
319				_, cmd := m.registryBrowser.submit(action)
320	
321				if m.registryBrowser.state != browserStateInput {
322					t.Errorf("state = %d, want the form", m.registryBrowser.state)
323				}
324				warn, ok := testutil.MsgOf[RegistryBrowserWarnMsg](cmd)
325				if !ok {
326					t.Fatal("no RegistryBrowserWarnMsg")
327				}
328				if warn.Text != "No registry selected" {
