332				if m.footer.Level() != components.LevelWarning {
333					t.Errorf("footer level = %v, want warning", m.footer.Level())
334				}
335				if fake.calls() != 0 || len(rec.repos()) != 0 {
336					t.Error("something was requested")
337				}
338			})
