9	// formAction is what a button of the browser form starts.
10	type formAction int
11	
12	const (
13		actionSearch   formAction = iota // IS-01 routing: short name + Searcher -> level 1, else tags
14		actionOpenTags                   // IS-11: always the tag lookup of the typed name
15	)
16	
17	// submit validates the form and starts action. An empty name starts nothing;
18	// no checked registry warns. actionSearch sends a name with no "/" to the image
19	// search when a Searcher is injected (level 1), anything else lists tags;
20	// actionOpenTags always lists the tags of the typed name.
21	func (b *RegistryBrowser) submit(action formAction) (*RegistryBrowser, tea.Cmd) {
22		repo := strings.TrimSpace(b.repoInput.Value())
23		if repo == "" {
24			return b, nil
25		}
26		var entries []browserRegistryEntry
27		for _, entry := range b.entries {
28			if b.selected(entry) {
29				entries = append(entries, entry)
30			}
31		}
32		if len(entries) == 0 {
33			return b, func() tea.Msg { return RegistryBrowserWarnMsg{Text: "No registry selected"} }
34		}
35		if action == actionSearch && b.searcher != nil && !strings.Contains(repo, "/") {
36			return b.startImageSearch(repo, entries)
37		}
38		return b.startTagLookup(repo, entries)
39	}
